//! Internal helpers used by the code generated by `#[derive(AssetCollection)]`.

use std::any::{TypeId, type_name};
use std::error::Error;
use std::fmt;

use bevy_asset::{Asset, AssetPath, AssetServer, Assets, Handle, LoadedFolder, UntypedHandle};
use bevy_ecs::world::World;
use bevy_platform::collections::HashMap;
use bevy_reflect::TypePath;

use crate::dynamic_asset::{DynamicAsset, DynamicAssetType};

// The generated code names Bevy types through these re-exports
pub use bevy_asset;
pub use bevy_ecs;
#[cfg(any(feature = "2d", feature = "3d"))]
pub use bevy_image;
#[cfg(feature = "2d")]
pub use bevy_math;
#[cfg(feature = "3d")]
pub use bevy_pbr;
pub use bevy_platform;

/// A collection field type that holds handles of a single asset type.
pub trait TypedHandleField {
    /// The asset type behind the field's handles.
    type Asset: Asset;
}

impl<A: Asset> TypedHandleField for Handle<A> {
    type Asset = A;
}

impl<T: TypedHandleField> TypedHandleField for Option<T> {
    type Asset = T::Asset;
}

impl<A: Asset> TypedHandleField for Vec<Handle<A>> {
    type Asset = A;
}

impl<K, A: Asset, S> TypedHandleField for HashMap<K, Handle<A>, S> {
    type Asset = A;
}

/// Loading of an asset collection field failed, because the field's asset type is not
/// registered with the app.
#[derive(Debug)]
pub struct UnregisteredAssetType {
    collection: &'static str,
    field: &'static str,
    asset_type: &'static str,
}

impl UnregisteredAssetType {
    fn of_field<C, F: TypedHandleField>(field: &'static str) -> Self {
        let collection = type_name::<C>();
        let collection = collection.rsplit("::").next().unwrap_or(collection);
        Self {
            collection,
            field,
            asset_type: F::Asset::short_type_path(),
        }
    }
}

impl fmt::Display for UnregisteredAssetType {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let Self {
            collection,
            field,
            asset_type,
        } = self;
        write!(
            f,
            "Asset collection field `{collection}::{field}` holds handles of `{asset_type}`, \
            but that asset type is not registered with the app. \
            Add the plugin that provides it or call `app.init_asset::<{asset_type}>()`."
        )
    }
}

impl Error for UnregisteredAssetType {}

/// The asset type of the field `field` points to, or a handle that fails to load with an
/// [`UnregisteredAssetType`] error if that type is not registered.
fn registered_asset_type<C, F: TypedHandleField>(
    world: &World,
    field_name: &'static str,
) -> Result<TypeId, UntypedHandle> {
    if world.contains_resource::<Assets<F::Asset>>() {
        return Ok(TypeId::of::<F::Asset>());
    }
    let error = UnregisteredAssetType::of_field::<C, F>(field_name);
    let failing = world
        .resource::<AssetServer>()
        .add_async::<LoadedFolder, _>(async move { Err(error) });
    Err(failing.untyped())
}

/// The asset type of the field `field` points to, while creating the collection.
///
/// # Panics
/// If the asset type is not registered. With a loading state, the collection is only created
/// after all fields loaded, which requires the asset types to be registered.
pub fn asset_type_of_field<C, F: TypedHandleField>(
    world: &World,
    _field: fn(&C) -> &F,
    field_name: &'static str,
) -> TypeId {
    if !world.contains_resource::<Assets<F::Asset>>() {
        panic!("{}", UnregisteredAssetType::of_field::<C, F>(field_name));
    }
    TypeId::of::<F::Asset>()
}

/// Load `paths` as the asset type of the field `field` points to.
pub fn load_paths<C, F: TypedHandleField>(
    world: &World,
    _field: fn(&C) -> &F,
    field_name: &'static str,
    paths: &[&'static str],
) -> Vec<UntypedHandle> {
    if let Err(failing) = registered_asset_type::<C, F>(world, field_name) {
        return vec![failing];
    }
    let asset_server = world.resource::<AssetServer>();
    paths
        .iter()
        .map(|path| asset_server.load::<F::Asset>(*path).untyped())
        .collect()
}

/// Load a dynamic asset as the asset type of the field `field` points to.
pub fn load_dynamic<C, F: TypedHandleField>(
    world: &mut World,
    asset: &dyn DynamicAsset,
    _field: fn(&C) -> &F,
    field_name: &'static str,
) -> Vec<UntypedHandle> {
    match registered_asset_type::<C, F>(world, field_name) {
        Ok(asset_type) => asset.load_as(world, asset_type),
        Err(failing) => vec![failing],
    }
}

/// Build a dynamic asset loaded with [`load_dynamic`].
pub fn build_dynamic(
    asset: &dyn DynamicAsset,
    asset_type: TypeId,
    world: &mut World,
) -> Result<DynamicAssetType, anyhow::Error> {
    asset.build_as(world, asset_type)
}

/// Load a folder as the asset type of the field `field` points to.
pub fn load_folder<C, F: TypedHandleField>(
    world: &mut World,
    _field: fn(&C) -> &F,
    field_name: &'static str,
    path: &'static str,
) -> UntypedHandle {
    match registered_asset_type::<C, F>(world, field_name) {
        Ok(asset_type) => crate::typed_folder::load_folder_as(world, path, asset_type).untyped(),
        Err(failing) => failing,
    }
}

/// The handle of a folder loaded with [`load_folder`].
pub fn folder_handle<'a>(
    world: &World,
    path: impl Into<AssetPath<'a>>,
    asset_type: TypeId,
) -> Option<Handle<LoadedFolder>> {
    crate::typed_folder::get_folder_as(world, path, asset_type)
}
